import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CXX_0q1Z.js";var i=JSON.parse(`{"title":"Events","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/storage/events.md","filePath":"en/modules/storage/events.md","lastUpdated":0}`),a={name:`en/modules/storage/events.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="events" tabindex="-1">Events <a class="header-anchor" href="#events" aria-label="Permalink to “Events”">​</a></h1><p>All four are synchronous cancellable pre-transaction events on the storage owner&#39;s entity thread. Item values are defensive snapshots and event business fields are read-only.</p><table tabindex="0"><thead><tr><th>Event</th><th>Timing</th><th>Cancellation effect</th></tr></thead><tbody><tr><td><code>StorageDepositEvent</code></td><td>Immediately before inventory removal and entry-table mutation</td><td>Aborts the whole transaction; inventory and storage remain unchanged.</td></tr><tr><td><code>StorageWithdrawEvent</code></td><td>Before the stored entry is debited</td><td>Aborts the whole transaction; stored amount remains unchanged.</td></tr><tr><td><code>StorageUnlockEvent</code></td><td>After price calculation, before currency/item charge and slot addition</td><td>Prevents payment and purchased-slot addition.</td></tr><tr><td><code>StorageBatchEvent</code></td><td>Before an atomic batch is committed, ahead of any escrow debit or write</td><td>Aborts the whole batch. Per-op deposit and withdraw events are deliberately not fired inside a batch.</td></tr></tbody></table><p>Accessors are record-style without a <code>get</code> prefix. Deposit and withdraw carry <code>playerId()</code>, <code>template()</code>, <code>requestedAmount()</code> and <code>source()</code> (<code>gui</code> / <code>command</code> / <code>api</code> / <code>action</code>), and withdraw adds <code>storedAmount()</code>. <code>StorageUnlockEvent</code> carries <code>slotAmount()</code>, <code>purchasedSlotsBefore()</code>, <code>currencyCost()</code> (<strong>currency only</strong> — an item price is not reflected in this event) and <code>source()</code>. <code>StorageBatchEvent</code> carries <code>ops()</code>, <code>allOrNothing()</code> and <code>source()</code>. Administrative <code>grantSlotsAsync</code> does not fire <code>StorageUnlockEvent</code>.</p><p>These events are emitted by the runtime transaction paths. No synthetic event is published when the bridge is unavailable; the future-returning facade operations report explicit result failures.</p>`,5)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};